grid=[[2]*10]+[[0]*10 for _ in range(9)]
components=[(3,[(1,2),(1,3)]),(3,[(5,4),(5,5)]),(3,[(8,0),(9,0)]),(6,[(1,7),(2,7)]),(6,[(4,8),(4,9)]),(7,[(2,5),(3,5)]),(8,[(3,1),(3,2)]),(9,[(6,2),(7,2)]),(4,[(6,8),(7,8)]),(1,[(8,5),(8,6)]),(5,[(9,7),(9,8)])]
# maintain components, move upward in ascending top coordinate, repeating until no movement
while True:
    moved=False
    components.sort(key=lambda x:min(r for r,c in x[1]))
    for i,(color,cells) in enumerate(components):
        occupied={p for j,(_,cs) in enumerate(components) if j!=i for p in cs}
        if all(r-1>=1 and (r-1,c) not in occupied for r,c in cells):
            components[i]=(color,[(r-1,c) for r,c in cells]); moved=True
    if not moved: break
out=[[0]*10 for _ in range(10)];out[0]=[2]*10
for color,cells in components:
    for r,c in cells: out[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in out))
